INSERT INTO chambre (nom, fantome, description, niveau_frayeur, prix_nuit, photo) VALUES
('La chambre de la mariée éternelle', 'Éléonore de Valombre', 'Éléonore de Valombre, morte en 1892 à 24 ans. Éléonore devait se marier dans cette chambre. Mais le soir de son mariage, elle découvrit une lettre révélant que son fiancé l''avait trahie. Désespérée, elle disparut mystérieusement cette nuit-là. Depuis, les clients entendent des pleurs derrière le miroir et aperçoivent une femme en robe blanche qui murmure : « Il va revenir… »', 3, 119.00, 'chambre-mariee.webp'),
('La chambre des murmures', 'Gabriel Moreau', 'Gabriel Moreau, mort en 1911 à 9 ans. Gabriel était un petit garçon qui séjournait à l''hôtel avec ses parents. Une nuit, il disparut sans laisser de traces. On raconte qu''il s''était caché dans une vieille armoire et qu''il n''en est jamais ressorti. Aujourd''hui, à minuit pile, les clients entendent un rire d''enfant, des petits pas dans le couloir et un jouet qui se met à bouger tout seul…', 1, 79.00, 'chambre-murmures.webp'),
('La chambre du fauteuil maudit', 'Victor Blackwood', 'Victor Blackwood, mort en 1876 à 68 ans. Victor était l''ancien propriétaire de l''hôtel. Il connaissait tous ses secrets et refusait de quitter les lieux. Un soir d''orage, il fut retrouvé mort dans son fauteuil, une montre arrêtée à 3 h 13. Depuis, les lumières de la chambre s''éteignent toutes seules. Certains clients affirment sentir une main glacée sur leur épaule et entendre une voix murmurer : « Cette chambre est à moi… »', 5, 149.00, 'chambre-fauteuil.webp');